-- PostgreSQL initial schema: generated from the reviewed 0002 contract. No demo or users.

CREATE TABLE "customers"(
 "id" TEXT PRIMARY KEY NOT NULL,
 "name" TEXT NOT NULL,
 "phone" TEXT NOT NULL,
 "created_at" TEXT NOT NULL
);

CREATE TABLE "order_events"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "order_id" INTEGER NOT NULL,
 "status" TEXT NOT NULL,
 "actor" TEXT NOT NULL,
 "created_at" TEXT NOT NULL
);

CREATE TABLE "order_items"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "order_id" INTEGER NOT NULL,
 "product_id" INTEGER NOT NULL,
 "code" TEXT NOT NULL,
 "name" TEXT NOT NULL,
 "size" TEXT NOT NULL,
 "image" TEXT NOT NULL,
 "price" INTEGER NOT NULL,
 "quantity" INTEGER NOT NULL,
 "subtotal" BIGINT NOT NULL,
 "variant_id" INTEGER,
 "sku" TEXT,
 "brand" TEXT,
 "kind" TEXT,
 "old_price" BIGINT,
 "discount" INTEGER,
 CONSTRAINT "order_items_check_0" CHECK("order_items"."quantity" > 0)
);

CREATE TABLE "orders"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "request_key" TEXT NOT NULL,
 "fingerprint" TEXT NOT NULL,
 "customer_id" TEXT NOT NULL,
 "name" TEXT NOT NULL,
 "phone" TEXT NOT NULL,
 "address" TEXT NOT NULL,
 "city" TEXT NOT NULL,
 "notes" TEXT NOT NULL,
 "payment" TEXT NOT NULL,
 "subtotal" BIGINT NOT NULL,
 "shipping" INTEGER,
 "total" BIGINT NOT NULL,
 "status" TEXT NOT NULL DEFAULT 'Pendiente',
 "created_at" TEXT NOT NULL,
 "version" INTEGER NOT NULL DEFAULT 0,
 "change_token" TEXT,
 "payment_method_id" INTEGER,
 "whatsapp_number" TEXT
);

CREATE TABLE "products"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "code" TEXT NOT NULL,
 "name" TEXT NOT NULL,
 "brand" TEXT NOT NULL,
 "category" TEXT NOT NULL,
 "gender" TEXT NOT NULL,
 "description" TEXT NOT NULL,
 "price" INTEGER NOT NULL,
 "old_price" BIGINT,
 "size" TEXT NOT NULL,
 "stock" INTEGER NOT NULL DEFAULT 0,
 "reserved" INTEGER NOT NULL DEFAULT 0,
 "sold" INTEGER NOT NULL DEFAULT 0,
 "images" TEXT NOT NULL,
 "tags" TEXT NOT NULL,
 "featured" INTEGER NOT NULL DEFAULT 0,
 "active" INTEGER NOT NULL DEFAULT 1,
 "search_text" TEXT NOT NULL,
 "created_at" TEXT NOT NULL,
 "version" INTEGER NOT NULL DEFAULT 0,
 "slug" TEXT,
 "edit_token" TEXT,
 "brand_id" INTEGER,
 "editorial_state" TEXT NOT NULL DEFAULT 'borrador',
 "concentration" TEXT,
 "performance" TEXT,
 "projection" TEXT,
 "occasion" TEXT NOT NULL DEFAULT '[]',
 "season" TEXT NOT NULL DEFAULT '[]',
 "is_new" INTEGER NOT NULL DEFAULT 0,
 "updated_at" TEXT,
 CONSTRAINT "products_check_0" CHECK(editorial_state IN('borrador','publicado','archivado')),
 CONSTRAINT "products_check_1" CHECK("products"."stock" >= "products"."reserved" AND "products"."reserved" >= 0 AND "products"."sold" >= 0),
 CONSTRAINT "products_check_2" CHECK("products"."price" >= 0)
);

CREATE TABLE "rate_limits"(
 "key" TEXT PRIMARY KEY NOT NULL,
 "count" INTEGER NOT NULL,
 "reset_at" BIGINT NOT NULL
);

CREATE TABLE "sessions"(
 "token_hash" TEXT PRIMARY KEY NOT NULL,
 "user_id" INTEGER NOT NULL,
 "expires_at" BIGINT NOT NULL
);

CREATE TABLE "settings"(
 "key" TEXT PRIMARY KEY NOT NULL,
 "value" TEXT NOT NULL
);

CREATE TABLE "users"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "username" TEXT NOT NULL,
 "name" TEXT NOT NULL,
 "password_hash" TEXT NOT NULL,
 "role" TEXT NOT NULL DEFAULT 'advisor',
 "active" INTEGER NOT NULL DEFAULT 1,
 "created_at" TEXT NOT NULL
);

CREATE TABLE "transaction_checks"(
 "ok" INTEGER NOT NULL,
 CONSTRAINT "transaction_checks_check_0" CHECK(ok=1)
);

CREATE TABLE "brands"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "name" TEXT NOT NULL,
 "slug" TEXT NOT NULL,
 "description" TEXT NOT NULL DEFAULT '',
 "image" TEXT,
 "active" INTEGER NOT NULL DEFAULT 1,
 "version" INTEGER NOT NULL DEFAULT 0,
 "search_text" TEXT NOT NULL DEFAULT '',
 CONSTRAINT "brands_check_0" CHECK(active IN(0,1))
);

CREATE TABLE "olfactory_families"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "name" TEXT NOT NULL,
 "slug" TEXT NOT NULL,
 "description" TEXT NOT NULL DEFAULT '',
 "image" TEXT,
 "active" INTEGER NOT NULL DEFAULT 1,
 "version" INTEGER NOT NULL DEFAULT 0,
 "search_text" TEXT NOT NULL DEFAULT '',
 CONSTRAINT "olfactory_families_check_0" CHECK(active IN(0,1))
);

CREATE TABLE "categories"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "name" TEXT NOT NULL,
 "slug" TEXT NOT NULL,
 "description" TEXT NOT NULL DEFAULT '',
 "image" TEXT,
 "active" INTEGER NOT NULL DEFAULT 1,
 "version" INTEGER NOT NULL DEFAULT 0,
 "search_text" TEXT NOT NULL DEFAULT '',
 CONSTRAINT "categories_check_0" CHECK(active IN(0,1))
);

CREATE TABLE "notes"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "name" TEXT NOT NULL,
 "slug" TEXT NOT NULL,
 "description" TEXT NOT NULL DEFAULT '',
 "image" TEXT,
 "active" INTEGER NOT NULL DEFAULT 1,
 "version" INTEGER NOT NULL DEFAULT 0,
 "search_text" TEXT NOT NULL DEFAULT '',
 "family_id" INTEGER,
 CONSTRAINT "notes_check_0" CHECK(active IN(0,1))
);

CREATE TABLE "product_notes"(
 "product_id" INTEGER NOT NULL,
 "note_id" INTEGER NOT NULL,
 "phase" TEXT NOT NULL,
 "position" INTEGER NOT NULL DEFAULT 0,
 CONSTRAINT "product_notes_product_id_note_id_phase_pk" PRIMARY KEY("product_id","note_id","phase"),
 CONSTRAINT "product_notes_check_0" CHECK(phase IN('salida','corazon','fondo'))
);

CREATE TABLE "product_categories"(
 "product_id" INTEGER NOT NULL,
 "category_id" INTEGER NOT NULL,
 CONSTRAINT "product_categories_product_id_category_id_pk" PRIMARY KEY("product_id","category_id")
);

CREATE TABLE "product_images"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "product_id" INTEGER NOT NULL,
 "url" TEXT NOT NULL,
 "alt" TEXT NOT NULL,
 "position" INTEGER NOT NULL DEFAULT 0,
 "source" TEXT,
 "authorization" TEXT
);

CREATE TABLE "product_variants"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "product_id" INTEGER NOT NULL,
 "sku" TEXT NOT NULL,
 "kind" TEXT NOT NULL,
 "size_ml" DOUBLE PRECISION NOT NULL,
 "price" INTEGER,
 "old_price" BIGINT,
 "stock" INTEGER,
 "reserved" INTEGER NOT NULL DEFAULT 0,
 "sold" INTEGER NOT NULL DEFAULT 0,
 "active" INTEGER NOT NULL DEFAULT 1,
 "commercial_verified" INTEGER NOT NULL DEFAULT 0,
 "version" INTEGER NOT NULL DEFAULT 0,
 CONSTRAINT "product_variants_check_0" CHECK(kind IN('frasco','decant')),
 CONSTRAINT "product_variants_check_1" CHECK(size_ml>0),
 CONSTRAINT "product_variants_check_2" CHECK(price IS NULL OR price>0),
 CONSTRAINT "product_variants_check_3" CHECK(old_price IS NULL OR old_price>0),
 CONSTRAINT "product_variants_check_4" CHECK(active IN(0,1)),
 CONSTRAINT "product_variants_check_5" CHECK(commercial_verified IN(0,1)),
 CONSTRAINT "valid_variant_inventory" CHECK((stock IS NOT NULL AND stock>=reserved OR stock IS NULL AND reserved=0) AND reserved>=0 AND sold>=0)
);

CREATE TABLE "collections"(
 "edit_token" TEXT,
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "name" TEXT NOT NULL,
 "slug" TEXT NOT NULL,
 "description" TEXT NOT NULL DEFAULT '',
 "image" TEXT,
 "mode" TEXT NOT NULL,
 "active" INTEGER NOT NULL DEFAULT 1,
 "version" INTEGER NOT NULL DEFAULT 0,
 CONSTRAINT "collections_check_0" CHECK(mode IN('manual','automatic'))
);

CREATE TABLE "collection_products"(
 "collection_id" INTEGER NOT NULL,
 "product_id" INTEGER NOT NULL,
 CONSTRAINT "collection_products_collection_id_product_id_pk" PRIMARY KEY("collection_id","product_id")
);

CREATE TABLE "collection_rules"(
 "collection_id" INTEGER NOT NULL,
 "field" TEXT NOT NULL,
 "value" TEXT NOT NULL,
 CONSTRAINT "collection_rules_collection_id_field_value_pk" PRIMARY KEY("collection_id","field","value")
);

CREATE TABLE "store_settings"(
 "id" INTEGER PRIMARY KEY NOT NULL,
 "data" TEXT NOT NULL,
 "version" INTEGER NOT NULL DEFAULT 0,
 CONSTRAINT "store_settings_check_0" CHECK(id=1)
);

CREATE TABLE "payment_methods"(
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
 "label" TEXT NOT NULL,
 "image" TEXT,
 "position" INTEGER NOT NULL DEFAULT 0,
 "active" INTEGER NOT NULL DEFAULT 1,
 "version" INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE "social_posts"(
